<template>
  <div class="mystery-page">
    <header class="page-head"><div><h1>奇闻故事</h1><p>真实案件、离奇事件与精彩人物。保留原作的推进与情绪，把完整故事讲清楚。</p></div><div class="actions"><button class="btn btn-primary" @click="openImport"><Plus :size="15" />导入视频</button><button class="btn" @click="openCollection"><ListPlus :size="15" />批量采集</button><button class="btn" @click="accountDialog = 'huasheng'"><Users :size="15" />华生账号</button><button class="btn btn-ghost" @click="settingsDialog?.showModal()"><Settings2 :size="15" />设置</button></div></header>
    <nav class="view-tabs" aria-label="奇闻故事工作区"><button v-for="view in views" :key="view.id" :class="{ active: activeView === view.id }" :aria-current="activeView === view.id ? 'page' : undefined" @click="changeView(view.id)">{{ view.label }}</button></nav>
    <div v-if="pageError" class="alert error" role="alert"><span>{{ pageError }}</span><button class="btn btn-sm" :disabled="loading" @click="refresh">重新加载</button></div>
    <div v-if="notice" class="notice" role="status">{{ notice }}</div>

    <template v-if="activeView === 'channels'">
      <section class="channels-panel"><header class="section-head"><div><h2>来源频道</h2><p class="note">按频道配置采集范围，使用视频 ID 去重。</p></div><button class="btn" @click="channelDialog?.showModal()"><Plus :size="14" />添加频道</button></header>
        <div v-if="!channels.length" class="empty"><RadioTower :size="30" /><strong>还没有来源频道</strong><p>添加 YouTube 频道后，即可按目标数量批量采集。</p><button class="btn" @click="channelDialog?.showModal()">添加第一个频道</button></div>
        <ul v-else class="channel-list"><li v-for="channel in channels" :key="channel.id"><div><strong>{{ channel.name || channel.url }}</strong><a :href="channel.url" target="_blank" rel="noreferrer">{{ channel.url }}</a><span class="note">{{ categories[channel.category] }}</span></div><label class="toggle"><input type="checkbox" :checked="channel.enabled" :disabled="!!busy" @change="toggleChannel(channel)" />启用采集</label></li></ul>
      </section>
      <section class="batch-panel"><header class="section-head"><h2>采集批次</h2><button class="btn btn-ghost btn-sm" @click="refresh">刷新</button></header><p v-if="!collections.length" class="note">尚未启动采集。批次会记录扫描、跳过、选中和异常原因。</p><p v-if="collections.length" class="note">暂停新增处理后，已启动的故事继续执行；停止单个故事可进入其运行记录。</p>
        <article v-for="batch in collections" :key="batch.id" class="batch-card"><header><strong>{{ targetLabels[batch.target] }} · 目标 {{ batch.targetCount }} 条</strong><span class="badge" :class="batch.status">{{ statusLabels[batch.status] || batch.status }}</span></header><p>{{ batch.message }}</p><p class="note">扫描 {{ batch.scanned }} · 跳过 {{ batch.skipped }} · 已选 {{ batch.storyIds.length }} · 采集异常 {{ batch.errors.length }}</p><p v-if="batch.counts" class="note">口播 {{ batch.counts.transcribed }} · 文稿 {{ batch.counts.drafts }} · 成片 {{ batch.counts.videos }} · 失败 {{ batch.counts.failed }} · 已发表 {{ batch.counts.published }}</p><details v-if="batch.errors.length"><summary>查看异常</summary><ul><li v-for="(error, index) in batch.errors" :key="index">{{ error }}</li></ul></details><div class="actions"><button v-if="['running', 'queued'].includes(batch.status)" class="btn btn-sm" :disabled="!!busy" @click="batchAction(batch, 'stop')">暂停新增处理</button><button v-else-if="batch.status !== 'completed'" class="btn btn-sm" :disabled="!!busy" @click="batchAction(batch, 'resume')">继续原批次</button><button v-if="batch.counts?.failed && !['running', 'queued'].includes(batch.status)" class="btn btn-sm" :disabled="!!busy" @click="batchAction(batch, 'retry')">只重试失败项</button><button v-for="id in batch.storyIds" :key="id" class="btn btn-ghost btn-sm" @click="openBatchStory(id)">故事 #{{ id }}</button></div></article>
      </section>
    </template>

    <template v-else>
      <div class="summary"><span>全部 <b>{{ counts.total || 0 }}</b></span><span>处理中 <b>{{ counts.running || 0 }}</b></span><span>可用 <b>{{ (counts.ready || 0) + (counts.completed || 0) }}</b></span><span>待处理 <b>{{ counts.needs_attention || 0 }}</b></span><span>已暂停 <b>{{ counts.paused || 0 }}</b></span></div>
      <div class="filters"><label class="search"><Search :size="15" /><input v-model="search" type="search" aria-label="搜索故事" placeholder="搜索标题、频道或故事" @input="scheduleFilter" /></label><select v-model="categoryFilter" aria-label="故事分类筛选" @change="filterChanged"><option value="">所有类别</option><option v-for="(label, key) in categories" :key="key" :value="key">{{ label }}</option></select><select v-model="statusFilter" aria-label="故事状态筛选" @change="filterChanged"><option value="">所有状态</option><option v-for="(label, key) in statusLabels" :key="key" :value="key">{{ label }}</option></select><button class="btn btn-ghost" aria-label="刷新故事列表" :disabled="loading" @click="refresh"><RefreshCw :size="16" :class="{ spin: loading }" /></button></div>
      <section class="workspace" :class="{ 'show-detail': mobileDetail }" aria-label="奇闻故事工作台">
        <aside class="queue-pane" aria-label="故事列表"><div v-if="loading && !stories.length" class="empty"><LoaderCircle :size="26" class="spin" /><p>正在读取故事…</p></div><div v-else-if="!stories.length" class="empty"><BookOpen :size="28" /><strong>{{ total ? '没有符合筛选条件的故事' : '还没有故事' }}</strong><p>导入一个 YouTube 视频，或从频道批量采集。</p><button class="btn" @click="openImport">导入视频</button></div><ul v-else class="queue-list"><li v-for="story in stories" :key="story.id"><button class="queue-item" :class="{ selected: selectedId === story.id }" :aria-current="selectedId === story.id ? 'true' : undefined" @click="selectStory(story.id)"><span class="note">{{ categories[story.category] }} · #{{ story.id }}</span><strong>{{ story.title || '等待读取视频标题' }}</strong><span class="queue-meta"><span class="badge" :class="story.status">{{ statusLabels[story.status] || story.status }}</span><span>{{ stageLabels[story.stage] || story.stage }}</span></span><span v-if="draftIsDirty(story.id)" class="dirty-label">有未保存修改</span></button></li></ul><footer v-if="total > pageSize" class="pagination"><button class="btn btn-sm" :disabled="page <= 1 || loading" @click="changePage(-1)">上一页</button><span>{{ page }} / {{ Math.ceil(total / pageSize) }}</span><button class="btn btn-sm" :disabled="page * pageSize >= total || loading" @click="changePage(1)">下一页</button></footer></aside>
        <section class="detail-pane" aria-label="故事详情" :aria-busy="detailLoading"><button class="btn btn-ghost btn-sm back" @click="mobileDetail = false"><ArrowLeft :size="14" />返回故事列表</button><div v-if="!selected || !editor" class="empty detail-empty"><BookOpen :size="32" /><h2>{{ detailError ? '故事暂时无法读取' : '从一个完整故事开始' }}</h2><p>{{ detailError || '选择故事，查看原稿、轻改对照与制作进度。' }}</p><button v-if="detailError" class="btn" @click="loadDetail(selectedId)">重试读取</button></div>
          <template v-else><header class="detail-head"><div><h2>{{ selected.title || '新故事' }}</h2><div class="detail-meta"><span class="badge" :class="selected.status">{{ statusLabels[selected.status] }}</span><span>{{ categories[selected.category] }}</span><a :href="selected.sourceUrl" target="_blank" rel="noreferrer">YouTube 来源<ExternalLink :size="12" /></a><span>故事 #{{ selected.id }}</span></div></div><button class="btn btn-ghost btn-sm" :disabled="running || !!busy" :title="running ? '请先停止执行再归档' : '归档后保留来源、版本与成片'" @click="archiveStory"><Archive :size="14" />归档</button></header>
            <ol class="pipeline" aria-label="故事处理进度"><li v-for="step in progressSteps" :key="step.id" :class="{ active: step.stages.includes(selected.stage), done: step.done() }"><Check v-if="step.done()" :size="13" /><span v-else class="step-dot" />{{ step.label }}</li></ol>
            <div class="job-message" :class="{ warning: selected.status === 'needs_attention' }" role="status"><span>{{ selected.message || '来源已保存，可开始处理。' }}</span><button v-if="activeRun" class="btn btn-sm" :disabled="!!busy" @click="runAction(activeRun, 'stop')">停止本机执行</button><button v-else-if="resumableRun" class="btn btn-sm" :disabled="!!busy" @click="runAction(resumableRun, 'resume')">继续原任务</button></div>
            <p v-if="detailError" class="error" role="alert">{{ detailError }}</p><p v-if="actionError" class="error" role="alert">{{ actionError }}</p>
            <details v-if="editor.metaDirty && editor.baseVersion !== selected.version" class="conflict-panel"><summary>记录已更新，本机修改仍保留</summary><p class="note">先对照服务器上的最新内容。继续保存会将本机改动另存，既有成片不会变化。</p><strong>{{ selected.title }}</strong><pre>{{ selected.correctedTranscript || selected.transcript }}</pre><button class="btn btn-sm" :disabled="sourceProcessing || !!busy" @click="editor.baseVersion = selected.version; saveMetadata()">保留我的修改并保存</button></details>
            <details v-if="editor.patchesDirty && editor.baseRevisionId !== selected.currentRevisionId" class="conflict-panel"><summary>已有新文稿，本机修改仍保留</summary><pre>{{ selected.revisions.find(item => item.id === selected.currentRevisionId)?.text }}</pre><button class="btn btn-sm" :disabled="editingLocked || !!busy || staleRevision" @click="editor.baseRevisionId = selected.currentRevisionId; saveRevision()">以我的修改另存一个版本</button></details>
            <div class="detail-tabs" role="tablist" aria-label="故事内容"><button v-for="tab in tabs" :id="`mystery-tab-${tab.id}`" :key="tab.id" role="tab" :aria-selected="detailTab === tab.id" :aria-controls="`mystery-panel-${tab.id}`" :class="{ active: detailTab === tab.id }" @click="detailTab = tab.id">{{ tab.label }}</button></div>

            <section id="mystery-panel-source" v-show="detailTab === 'source'" role="tabpanel" aria-labelledby="mystery-tab-source" class="tab-panel">
              <blockquote v-if="sourceExcerpt" aria-label="已定位的原文依据">{{ sourceExcerpt }}</blockquote><div class="two-fields"><label class="field">故事标题<input v-model="editor.title" maxlength="120" @input="markMeta" /></label><div class="source-facts"><span>{{ selected.downloadMode === 'audio' ? '仅音频' : '完整视频' }}</span><span>{{ selected.sourceChannel || '频道元数据待获取' }}</span><a v-if="selected.sourceVideoUrl" :href="downloadUrl('source')" download>下载来源媒体</a></div></div>
              <video v-if="selected.sourceVideoUrl && selected.downloadMode === 'video'" ref="sourcePlayer" class="video-player source-player" :src="selected.sourceVideoUrl" controls playsinline preload="metadata" aria-label="原视频预览" /><audio v-else-if="selected.sourceVideoUrl" ref="sourcePlayer" :src="selected.sourceVideoUrl" controls preload="metadata" aria-label="原音频预览" /><div v-else class="media-empty"><Film :size="24" /><p>来源媒体下载后保留在这里，供转写与核对。</p></div>
              <details class="source-original"><summary>原始转写 · {{ selected.transcript.length }} 字</summary><pre>{{ selected.transcript || '尚未转写' }}</pre></details>
              <label class="field">校对稿<textarea ref="sourceTextArea" v-model="editor.correctedTranscript" class="transcript-editor" aria-label="校对稿" placeholder="完整转写会出现在这里，可修正错字、姓名和断句。" @input="markMeta" /></label><p class="note">校对稿用于后续分析和轻改。更改后会重新检查；已保存文稿和旧成片保留原版本。</p>
              <details v-if="selected.chunks.length" class="chunks"><summary>按转写块定位来源 · {{ selected.chunks.length }} 块</summary><ol><li v-for="(chunk, index) in selected.chunks" :key="index"><button class="btn btn-sm btn-ghost" :disabled="!selected.sourceVideoUrl" @click="seekSource(chunk.start)">{{ duration(chunk.start) }} — {{ duration(chunk.start + chunk.duration) }}</button><p>{{ chunk.text }}</p></li></ol><p class="note">这里是源视频的块级时间，不是成片字幕时间。</p></details>
              <details v-if="selected.translation" class="translation"><summary>中文保义译文 · {{ selected.translation.review.passed ? '已通过对照' : '需要核对' }}</summary><p class="note">原文逐句对应，后续理解和轻改以这份中文稿为底稿。</p><textarea ref="translatedTextArea" :value="selected.translation.text" readonly aria-label="中文保义译文" class="translation-text" /><ul v-if="selected.translation.review.issues.length"><li v-for="(issue, index) in selected.translation.review.issues" :key="index">{{ issue.message }}</li></ul><details><summary>查看原句与译句</summary><article v-for="segment in selected.translation.segments" :key="segment.id"><blockquote>{{ segment.sourceText }}</blockquote><p>{{ segment.text }}</p></article></details></details><div class="save-row"><span :class="{ dirty: editor.metaDirty }">{{ editor.metaDirty ? '有未保存修改，切换故事仍会保留' : '校对稿已保存' }}</span><button class="btn" :disabled="!editor.metaDirty || sourceProcessing || !!busy" @click="saveMetadata"><Save :size="14" />保存校对与资料</button></div>
            </section>

            <section id="mystery-panel-analysis" v-show="detailTab === 'analysis'" role="tabpanel" aria-labelledby="mystery-tab-analysis" class="tab-panel">
              <div v-if="!selected.analysis" class="empty"><ScanText :size="28" /><strong>等待理解完整原稿</strong><p>先辨明主题、讲述目的和观众心理，再逐段记录推进与情绪。</p></div><template v-else><dl class="analysis-summary"><div><dt>原稿主题</dt><dd>{{ selected.analysis.theme }}</dd></div><div><dt>为什么讲这个故事</dt><dd>{{ selected.analysis.purpose }}</dd></div><div><dt>作者态度</dt><dd>{{ selected.analysis.stance }}</dd></div><div><dt>观众心理与情绪需求</dt><dd><ul><li v-for="(need, index) in selected.analysis.audienceNeeds" :key="index">{{ need }}</li></ul></dd></div><div><dt>结尾如何兑现期待</dt><dd>{{ selected.analysis.endingPayoff }}</dd></div></dl>
                <h3 class="section-title">故事如何一步步推进</h3><ol class="beat-list"><li v-for="(beat, index) in selected.analysis.beats" :key="beat.id"><header><strong>{{ index + 1 }}. {{ beat.purpose }}</strong><button class="btn btn-ghost btn-sm" @click="locateSource(beat.start, beat.end)">查看原文</button></header><p><span>情绪：</span>{{ beat.emotion }}</p><p><span>讲法：</span>{{ beat.method }}</p><p><span>信息揭示：</span>{{ beat.reveal }}</p></li></ol>
                <details class="evidence"><summary>原文依据 · {{ selected.analysis.evidence.length }} 处</summary><article v-for="(item, index) in selected.analysis.evidence" :key="item.id || index"><blockquote>{{ item.quote }}</blockquote><p>{{ item.note }}</p><button class="btn btn-ghost btn-sm" @click="locateSource(item.start, item.end)">定位摘录</button></article></details>
                <details v-if="selected.analysis.identitySpans?.length"><summary>需要处理的作者信息与营销片段</summary><article v-for="(span, index) in selected.analysis.identitySpans" :key="index"><blockquote>{{ span.text }}</blockquote><p>{{ span.reason }}</p><button class="btn btn-ghost btn-sm" @click="locateSource(span.start, span.end)">定位原文</button></article></details>
                <details v-if="selected.analysis.dossier" class="dossier"><summary>故事档案 · 辅助回查</summary><p class="note">人物、事件与主张用于核对；正文仍保留原作者讲述顺序。</p><h4>人物与关系</h4><ul><li v-for="(person, index) in selected.analysis.dossier.people" :key="index"><strong>{{ person.name }}</strong><span v-if="person.aliases.length">（{{ person.aliases.join('、') }}）</span> · {{ person.role }}<button v-for="id in person.evidenceIds" :key="id" class="evidence-link" @click="locateEvidence(id)">依据 {{ id }}</button></li></ul><h4>事件时间线</h4><ol><li v-for="(event, index) in selected.analysis.dossier.timeline" :key="index"><strong>{{ event.when }}</strong> · {{ event.event }}<button v-for="id in event.evidenceIds" :key="id" class="evidence-link" @click="locateEvidence(id)">依据 {{ id }}</button></li></ol><h4>主张与依据</h4><ul><li v-for="(claim, index) in selected.analysis.dossier.claims" :key="index"><strong>{{ claim.claim }}</strong><p>{{ claim.basis }} · {{ certaintyLabels[claim.certainty] || claim.certainty }}</p><button v-for="id in claim.evidenceIds" :key="id" class="evidence-link" @click="locateEvidence(id)">依据 {{ id }}</button></li></ul><h4>尚未确定</h4><ul><li v-for="(item, index) in selected.analysis.dossier.uncertainties" :key="index">{{ item }}</li></ul></details>
              </template><label class="field section-title">补充资料与核对备注<textarea v-model="editor.notes" aria-label="补充资料与核对备注" placeholder="记录补充资料的来源、摘录和待核对问题。" @input="markMeta" /></label><label class="field">关联同题故事编号<input v-model="editor.relatedIds" placeholder="例如：12, 25" @input="markMeta" /></label><div class="save-row"><span class="note">手动记录资料，不会自动加入口播正文。</span><button class="btn" :disabled="!editor.metaDirty || sourceProcessing || !!busy" @click="saveMetadata">保存资料</button></div>
            </section>

            <section id="mystery-panel-script" v-show="detailTab === 'script'" role="tabpanel" aria-labelledby="mystery-tab-script" class="tab-panel">
              <div class="revision-bar"><label>文稿版本<select :value="editor.revisionId ?? ''" aria-label="文稿版本" @change="selectRevision(Number(eventValue($event)))"><option v-if="!selected.revisions.length" value="">尚未生成</option><option v-for="revision in [...selected.revisions].reverse()" :key="revision.id" :value="revision.id">v{{ revision.id }}{{ revision.id === selected.currentRevisionId ? ' · 当前版本' : ' · 历史版本' }}</option></select></label><a v-if="revision" :href="downloadUrl('script', undefined, revision.id)" download><Download :size="13" />下载文稿</a><a v-if="revision" :href="downloadUrl('analysis', undefined, revision.id)" download>下载拆解与对照</a></div>
              <div v-if="!revision" class="empty"><ScanText :size="28" /><strong>尚未生成轻改稿</strong><p>完成原稿理解后，在原文上提出必要修改，逐处检查句义和全文。</p></div><template v-else><div class="review-result" :class="{ warning: editor.patchesDirty || !revision.review?.passed || staleRevision }" role="status"><strong>{{ editor.patchesDirty ? '当前修改尚未保存和检查' : staleRevision ? '来源或人设已更新，此版本检查已过期' : revision.review?.passed ? '对照检查通过' : revision.review ? '对照检查需要处理' : '等待对照检查' }}</strong><p>句义 · 内容完整 · 连贯听感 · 原作主题与心理体验</p><ul v-if="!editor.patchesDirty && revision.review?.issues.length"><li v-for="(issue, index) in revision.review.issues" :key="index">{{ issue.message }}</li></ul></div>
                <MysteryScriptEditor :key="selected.id" :source="editor.patchSource" :patches="editor.patches" :analysis="revision.analysis" :selection="editor.selection" :disabled="editingLocked || !!busy || staleRevision" @update:patches="updatePatches" @update:selection="editor.selection = $event" />
                <div class="save-row"><span :class="{ dirty: editor.patchesDirty }">{{ editor.patchesDirty ? '未保存修改已保留在本机草稿' : `当前查看 v${revision.id}` }}</span><button class="btn" :disabled="!editor.patchesDirty || editingLocked || !!busy || staleRevision" @click="saveRevision"><Save :size="14" />另存版本并检查</button></div><p v-if="revision.id !== selected.currentRevisionId" class="note">正在查看历史版本。恢复或修改后另存版本，保留现有成片的原稿归属。</p>
              </template>
            </section>

            <section id="mystery-panel-production" v-show="detailTab === 'production'" role="tabpanel" aria-labelledby="mystery-tab-production" class="tab-panel"><header class="section-head"><h3>华生制作记录</h3><span class="note">当前文稿 {{ selected.currentRevisionId ? `v${selected.currentRevisionId}` : '尚未生成' }}</span></header><p v-if="selected.currentRevisionId && !selected.editions.some(item => item.revisionId === selected.currentRevisionId)" class="notice">当前文稿 v{{ selected.currentRevisionId }} 尚未制作。</p><div v-if="!selected.editions.length" class="empty"><Video :size="28" /><strong>尚未创建华生项目</strong><p>选择制作目标与账号后，自动沿原项目完成制作、导出和下载。</p></div><article v-for="edition in [...selected.editions].reverse()" :key="edition.id" class="edition-card"><header><strong>文稿 v{{ edition.revisionId }} · {{ editionStatus(edition.status) }}</strong><button v-if="edition.projectUrl" class="btn btn-ghost btn-sm" type="button" :disabled="!!busy" aria-label="打开原项目" title="在原版本绑定账号打开花生项目" @click="openEditionProject(edition)"><LoaderCircle v-if="busy === `open-project-${edition.id}`" :size="12" class="spin" />{{ busy === `open-project-${edition.id}` ? '正在打开…' : '打开原项目' }}<ExternalLink v-if="busy !== `open-project-${edition.id}`" :size="12" /></button></header><p>{{ edition.message }}</p><dl class="compact-details"><div><dt>绑定账号</dt><dd>{{ accountLabel(edition.accountName) }}</dd></div><div><dt>已确认应用</dt><dd>{{ edition.confirmedSettings.scheme || '尚无平台确认' }}</dd></div><div><dt>期望设置</dt><dd>{{ edition.requestedSettings.aspect }} · {{ edition.requestedSettings.voice }} · {{ edition.requestedSettings.subtitle }}</dd></div><div><dt>视觉说明</dt><dd>{{ edition.requestedSettings.visual }}</dd></div><div><dt>导出任务</dt><dd>{{ edition.exportTask?.taskId || '尚未获得导出编号' }}</dd></div></dl><p class="note">期望设置以平台实际确认结果为准。制作说明与口播正文分别保存。</p><button v-if="edition.videoUrl" class="btn btn-sm" @click="showEdition(edition.id)">查看该版本成片</button><details v-if="!edition.videoUrl && !running && recovery[edition.id]" class="recovery"><summary>补录原项目或原导出编号</summary><p class="note">创建或导出结果未知时，填写原任务信息继续核对。</p><form @submit.prevent="recoverEdition(edition)"><label v-if="!edition.projectUrl" class="field">原华生项目链接<input v-model="recovery[edition.id].projectUrl" type="url" /></label><template v-if="!edition.exportTask"><label class="field">原导出任务编号<input v-model="recovery[edition.id].taskId" /></label><label class="field">原导出版本标识<input v-model="recovery[edition.id].projectHash" maxlength="64" /></label></template><button class="btn btn-sm" type="submit" :disabled="!!busy || (!recovery[edition.id].projectUrl && !(recovery[edition.id].taskId && recovery[edition.id].projectHash))">保存恢复信息</button></form></details></article></section>

            <section id="mystery-panel-output" v-show="detailTab === 'output'" role="tabpanel" aria-labelledby="mystery-tab-output" class="tab-panel"><div class="revision-bar"><label>成片版本<select v-model="editionId" aria-label="成片版本"><option v-if="!selected.editions.length" value="">尚无成片</option><option v-for="item in [...selected.editions].reverse()" :key="item.id" :value="item.id">文稿 v{{ item.revisionId }} · {{ editionStatus(item.status) }}</option></select></label><span v-if="edition" class="note">绑定文稿 v{{ edition.revisionId }}{{ edition.revisionId !== selected.currentRevisionId ? ' · 非当前文稿版本' : '' }}</span></div><template v-if="edition"><video v-if="edition.videoUrl" :key="edition.videoUrl" class="video-player" :src="edition.videoUrl" controls playsinline preload="metadata" aria-label="奇闻故事成片预览" /><div v-else class="media-empty"><Video :size="30" /><strong>本地成片尚未就绪</strong><p>{{ edition.message || editionStatus(edition.status) }}</p></div><p v-if="edition.videoUrl" class="note media-info">{{ duration(edition.duration || 0) }} · {{ edition.width || '—' }} × {{ edition.height || '—' }} · {{ fileSize(edition.bytes) }} · 文稿 v{{ edition.revisionId }}</p><div class="file-links"><a v-if="edition.videoUrl" :href="downloadUrl('video', edition.id)" download><Download :size="14" />MP4</a><a :href="downloadUrl('script', edition.id, edition.revisionId)" download>文稿 TXT</a><a :href="downloadUrl('analysis', edition.id, edition.revisionId)" download>来源、拆解与对照</a><a v-if="edition.status === 'package_ready'" :href="downloadUrl('package', edition.id)" download>下载完整交付包</a><span class="note">暂无成片字幕文件</span></div>
                <section class="cover-section"><header class="section-head"><h3>标题与横竖封面</h3><span class="note">封面 v{{ edition.coverRevision || 0 }}</span></header><form v-if="copyDrafts[edition.id]" class="copy-form" @submit.prevent="saveCopy(edition)"><label v-if="edition.titleCandidates?.length" class="field">标题候选<select aria-label="标题候选" v-model="copyDrafts[edition.id].title" :disabled="publicationLocked(edition)"><option :value="copyDrafts[edition.id].title">{{ copyDrafts[edition.id].title }}</option><option v-for="candidate in edition.titleCandidates.filter(item => item !== copyDrafts[edition.id].title)" :key="candidate" :value="candidate">{{ candidate }}</option></select></label><label class="field">选定标题<input v-model="copyDrafts[edition.id].title" required maxlength="50" :disabled="publicationLocked(edition)" /></label><label class="field">简介<textarea v-model="copyDrafts[edition.id].description" required maxlength="2000" :disabled="publicationLocked(edition)" /></label><label class="field">标签（逗号分隔）<input v-model="copyDrafts[edition.id].tags" :disabled="publicationLocked(edition)" /></label><button class="btn btn-sm" :disabled="!!busy || running || publicationLocked(edition)" type="submit">保存标题与发布文案</button><p class="note">标题变更后需更新封面；已发送的发表内容保留原快照。</p></form><div class="cover-grid"><figure><img v-if="edition.landscapeCoverUrl" :src="edition.landscapeCoverUrl" alt="横版故事封面" /><div v-else class="cover-empty">横版封面待生成</div><figcaption>横版封面<a v-if="edition.landscapeCoverUrl" :href="downloadUrl('landscape', edition.id)" download>下载</a></figcaption></figure><figure><img v-if="edition.portraitCoverUrl" :src="edition.portraitCoverUrl" alt="竖版故事封面" /><div v-else class="cover-empty">竖版封面待生成</div><figcaption>竖版封面<a v-if="edition.portraitCoverUrl" :href="downloadUrl('portrait', edition.id)" download>下载</a></figcaption></figure></div><label class="field">封面设计要求<input v-model="coverInstructions[edition.id]" maxlength="1000" placeholder="例如：突出故事中的钥匙，使用短疑问标题；示意画面注明示意" /></label><button class="btn" :disabled="!edition.videoUrl || running || !!busy" @click="startRun('video', 'covers', edition)"><ImagePlus :size="14" />{{ edition.coverRevision ? '单独重做封面' : '生成封面' }}</button><p class="note">封面失败可单独继续，已完成的视频会保留。</p></section>
                <section class="publication"><header class="section-head"><h3>百家号发表</h3><button class="btn btn-ghost btn-sm" @click="accountDialog = 'baijiahao'">管理账号</button></header><div v-if="edition.publication" class="job-message"><strong>{{ publicationLabels[edition.publication.status] || edition.publication.status }}</strong><span>{{ edition.publication.message }}</span></div><details v-if="edition.publication?.result"><summary>平台回执</summary><pre>{{ JSON.stringify(edition.publication.result, null, 2) }}</pre></details><p v-if="edition.publication" class="note">发表绑定文稿 v{{ edition.revisionId }}、{{ accountLabel(edition.publication.accountName) }}及已提交素材。修改不会改变原请求。</p><button v-if="!edition.publication" class="btn" :disabled="edition.status !== 'package_ready' || running || !!busy" @click="openPublish(edition)">选择账号与发布文案</button><p v-if="edition.status !== 'package_ready'" class="note">成片与两张封面均就绪后，可准备发表。</p></section>
              </template><div v-else class="empty"><Video :size="30" /><strong>尚无成片记录</strong><p>本地 MP4 下载并通过检查后，会在这里提供预览。</p></div></section>

            <section id="mystery-panel-logs" v-show="detailTab === 'logs'" role="tabpanel" aria-labelledby="mystery-tab-logs" class="tab-panel"><h3>执行记录</h3><p v-if="!selected.runs.length" class="note">尚未开始执行。</p><article v-for="run in [...selected.runs].reverse()" :key="run.id" class="run-card"><header><strong>{{ targetLabels[run.target] }} · {{ stageLabels[run.stage] || run.stage }}</strong><span class="badge" :class="run.status">{{ statusLabels[run.status] || run.status }}</span></header><p>{{ run.message }}</p><p class="note">任务 {{ run.taskId || '待入队' }} · {{ formatTime(run.createdAt) }}<template v-if="run.revisionId"> · 文稿 v{{ run.revisionId }}</template></p><button v-if="['running', 'queued'].includes(run.status)" class="btn btn-sm" :disabled="!!busy" @click="runAction(run, 'stop')">停止本机执行</button><button v-else-if="['paused', 'needs_attention'].includes(run.status)" class="btn btn-sm" :disabled="running || !!busy" @click="runAction(run, 'resume')">继续原任务</button></article><h3 class="section-title">步骤日志</h3><ol class="logs"><li v-for="(log, index) in [...selected.logs].reverse()" :key="index"><time>{{ formatTime(log.at) }}</time><span>{{ log.message }}</span></li></ol></section>

            <footer class="production-bar"><div><strong>{{ selected.currentRevisionId ? `当前文稿 v${selected.currentRevisionId}` : '从来源开始' }}</strong><span v-if="draftIsDirty(selected.id)" class="dirty-label">请先保存未提交的修改</span><span v-else class="note">保持完整原稿的自然时长</span></div><label class="target-picker">目标<select v-model="runTarget" aria-label="处理目标"><option value="draft">只生成文稿</option><option value="video">制作视频</option><option value="publish">制作并发表百家号</option></select></label><label v-if="runTarget !== 'draft'" class="account-picker">华生账号<select v-model="huashengAccountName" aria-label="华生制作账号"><option value="">请选择账号</option><option v-for="account in accounts.huasheng.accounts" :key="account.accountName" :value="account.accountName">{{ account.label }}{{ account.status === 'ready' ? '' : ' · 需登录' }}</option></select></label><button class="btn btn-primary" :disabled="!!busy || running || draftIsDirty(selected.id) || (runTarget !== 'draft' && !huashengAccountName)" @click="runTarget === 'publish' ? openPublish(null) : startRun(runTarget)"><Play :size="14" />{{ runTarget === 'draft' ? '生成并检查文稿' : runTarget === 'publish' ? '设置制作与发表' : '开始制作视频' }}</button></footer>
          </template>
        </section>
      </section>
    </template>

    <dialog ref="importDialog" class="form-dialog" aria-labelledby="import-title"><form @submit.prevent="importStory"><header><h2 id="import-title">导入 YouTube 视频</h2><button type="button" class="btn btn-ghost btn-icon" aria-label="关闭导入" @click="importDialog?.close()"><X :size="18" /></button></header><div class="dialog-body"><label class="field">视频链接<input v-model="importForm.sourceUrl" type="url" required placeholder="https://www.youtube.com/watch?v=…" /></label><label class="field">故事标题（可留空）<input v-model="importForm.title" maxlength="120" /></label><label class="field">类别<select v-model="importForm.category"><option v-for="(label, key) in categories" :key="key" :value="key">{{ label }}</option></select></label><label class="field">来源下载<select v-model="importForm.downloadMode"><option value="video">完整视频（默认）</option><option value="audio">仅音频</option></select></label><p class="note">导入后选择处理目标。原视频与口播会保留用于核对。</p><p v-if="dialogError" class="error" role="alert">{{ dialogError }}</p></div><footer><button type="button" class="btn" @click="importDialog?.close()">取消</button><button type="submit" class="btn btn-primary" :disabled="!!busy || !importForm.sourceUrl.trim()">导入故事</button></footer></form></dialog>

    <dialog ref="channelDialog" class="form-dialog" aria-labelledby="channel-title"><form @submit.prevent="saveChannel"><header><h2 id="channel-title">添加来源频道</h2><button type="button" class="btn btn-ghost btn-icon" aria-label="关闭频道表单" @click="channelDialog?.close()"><X :size="18" /></button></header><div class="dialog-body"><label class="field">YouTube 频道链接<input v-model="channelForm.url" type="url" required placeholder="https://www.youtube.com/@channel/videos" /></label><label class="field">频道备注<input v-model="channelForm.name" required maxlength="100" /></label><label class="field">默认类别<select v-model="channelForm.category"><option v-for="(label, key) in categories" :key="key" :value="key">{{ label }}</option></select></label><p v-if="dialogError" class="error" role="alert">{{ dialogError }}</p></div><footer><button type="submit" class="btn btn-primary" :disabled="!!busy">保存频道</button></footer></form></dialog>

    <dialog ref="collectionDialog" class="form-dialog" aria-labelledby="collection-title"><form @submit.prevent="startCollection"><header><h2 id="collection-title">批量采集</h2><button type="button" class="btn btn-ghost btn-icon" aria-label="关闭批量采集" @click="collectionDialog?.close()"><X :size="18" /></button></header><div class="dialog-body"><fieldset><legend>选择频道</legend><p v-if="!channels.some(channel => channel.enabled)" class="note">暂无已启用频道，可在下方填写链接。</p><label v-for="channel in channels.filter(item => item.enabled)" :key="channel.id" class="check-row"><input v-model="collectionForm.channelIds" type="checkbox" :value="channel.id" />{{ channel.name || channel.url }}</label></fieldset><label class="field">补充频道或视频链接（每行一个）<textarea v-model="collectionForm.urls" rows="3" /></label><div class="two-fields"><label class="field">目标条数<input v-model.number="collectionForm.targetCount" type="number" min="1" max="100" required /></label><label class="field">默认类别<select v-model="collectionForm.category"><option v-for="(label, key) in categories" :key="key" :value="key">{{ label }}</option></select></label></div><label class="field">处理目标<select aria-label="批量处理目标" v-model="collectionForm.target"><option value="draft">只生成文稿</option><option value="video">制作视频</option><option value="publish">制作并发表百家号</option></select></label><label v-if="collectionForm.target !== 'draft'" class="field">华生账号<select v-model="collectionForm.huashengAccountName" required><option value="">请选择账号</option><option v-for="account in accounts.huasheng.accounts" :key="account.accountName" :value="account.accountName">{{ account.label }}</option></select></label><template v-if="collectionForm.target === 'publish'"><label class="field">百家号账号<select v-model="collectionForm.baijiahaoAccountName" aria-label="批量百家号账号" required><option value="">请选择账号</option><option v-for="account in accounts.baijiahao.accounts" :key="account.accountName" :value="account.accountName">{{ account.label }}</option></select></label><label class="field">创作声明<input v-model="collectionForm.creationDeclaration" aria-label="批量创作声明" required maxlength="100" placeholder="按当前平台与作品需要填写" /></label><label class="field">水印<select v-model="collectionForm.watermark" aria-label="批量水印" required><option value="">请选择水印设置</option><option value="添加水印">添加水印</option><option value="不添加水印">不添加水印</option></select></label><p class="note">每条故事使用各自生成的标题、简介和标签，发表到此次选择的账号。</p></template><label class="field">来源下载<select v-model="collectionForm.downloadMode"><option value="video">完整视频</option><option value="audio">仅音频</option></select></label><details><summary>筛选条件</summary><label class="field">标题关键词（逗号分隔）<input v-model="collectionForm.keywords" /></label><div class="two-fields"><label class="field">最短时长（秒）<input v-model.number="collectionForm.minSeconds" type="number" min="0" /></label><label class="field">最长时长（秒，0 为不限）<input v-model.number="collectionForm.maxSeconds" type="number" min="0" /></label></div><label class="field">发布日期不早于<input v-model="collectionForm.afterDate" type="date" /></label></details><p v-if="dialogError" class="error" role="alert">{{ dialogError }}</p></div><footer><button type="submit" class="btn btn-primary" :disabled="!!busy || (!collectionForm.channelIds.length && !collectionForm.urls.trim())">开始采集</button></footer></form></dialog>

    <dialog ref="settingsDialog" class="form-dialog" aria-labelledby="settings-title"><header><h2 id="settings-title">工作区设置</h2><button type="button" class="btn btn-ghost btn-icon" aria-label="关闭设置" @click="settingsDialog?.close()"><X :size="18" /></button></header><div class="dialog-body"><p>面向 40 岁以上观众，用清楚、具体、日常的中文讲述完整故事。</p><p class="note">每篇保留原作自身的主题、目的、推进方法和情绪心理满足；人设只影响必要的词句调整。</p><label v-if="editor" class="field section-title">当前故事的讲述人设<textarea v-model="editor.narrator" rows="5" @input="markMeta" /></label><button v-if="editor" class="btn" :disabled="!editor.metaDirty || sourceProcessing || !!busy" @click="saveMetadata">保存当前故事设置</button><div class="settings-accounts"><button class="btn" @click="settingsDialog?.close(); accountDialog = 'huasheng'">管理华生账号</button><button class="btn" @click="settingsDialog?.close(); accountDialog = 'baijiahao'">管理百家号账号</button></div><p class="note">新工作区使用独立账号。已有项目、导出与发表保留创建时的绑定。</p></div></dialog>

    <dialog ref="publishDialog" class="form-dialog" aria-labelledby="publish-title"><form @submit.prevent="publishEdition"><header><h2 id="publish-title">发表指定成片</h2><button type="button" class="btn btn-ghost btn-icon" aria-label="关闭发表" @click="publishDialog?.close()"><X :size="18" /></button></header><div class="dialog-body"><p v-if="publicationEditionId && edition" class="note">发表文稿 v{{ edition.revisionId }} 对应的成片与封面。</p><p v-else class="note">完成当前故事的原稿理解、轻改对照、华生制作与封面后，按本次设置发表。</p><label class="field">百家号账号<select v-model="publishForm.accountName" required><option value="">请选择账号</option><option v-for="account in accounts.baijiahao.accounts" :key="account.accountName" :value="account.accountName">{{ account.label }}</option></select></label><label class="field">标题<input v-model="publishForm.title" required maxlength="50" /></label><label class="field">简介<textarea v-model="publishForm.description" rows="4" required maxlength="2000" /></label><label class="field">标签（逗号分隔）<input v-model="publishForm.tags" /></label><label class="field">创作声明<input v-model="publishForm.creationDeclaration" required maxlength="100" placeholder="按当前平台与作品需要填写" /></label><label class="field">水印<select aria-label="水印" v-model="publishForm.watermark" required><option value="">请选择水印设置</option><option value="添加水印">添加水印</option><option value="不添加水印">不添加水印</option></select></label><p v-if="dialogError" class="error" role="alert">{{ dialogError }}</p></div><footer><button type="submit" class="btn btn-primary" :disabled="!!busy || !publishForm.accountName || !publishForm.title.trim() || !publishForm.description.trim() || !publishForm.creationDeclaration.trim() || !publishForm.watermark">提交到百家号</button></footer></form></dialog>
    <HuashengAccounts v-if="accountDialog === 'huasheng'" scope="mystery" @close="accountDialog = ''" @updated="updateAccounts('huasheng', $event)" /><BaijiahaoAccounts v-if="accountDialog === 'baijiahao'" api-base="/mystery-stories/accounts/baijiahao" @close="accountDialog = ''" @updated="updateAccounts('baijiahao', $event)" />
  </div>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { Archive, ArrowLeft, BookOpen, Check, Download, ExternalLink, Film, ImagePlus, ListPlus, LoaderCircle, Play, Plus, RadioTower, RefreshCw, Save, ScanText, Search, Settings2, Users, Video, X } from 'lucide-vue-next'
