const stageLabels: Record<string, string> = { download: '下载来源', transcribe: '转写口播', analyze: '理解原稿', edit: '原文轻改', review: '对照检查', produce: '华生制作', export: '导出下载', covers: '成片包装', publish: '百家号发表', completed: '已完成' }
const targetLabels = { draft: '只生成文稿', video: '制作视频', publish: '制作并发表' }
