const publicationLabels: Record<string, string> = { pending: '待上传', uploading: '上传中', submitted: '已提交待审核', published: '已发表', uncertain: '结果待核对', paused: '已暂停', failed: '需要处理' }
const views = [{ id: 'workbench', label: '生产工作台' }, { id: 'library', label: '故事库' }, { id: 'channels', label: '频道采集' }, { id: 'outputs', label: '成片与发表' }]
const tabs = [{ id: 'source', label: '原视频与口播' }, { id: 'analysis', label: '原稿理解' }, { id: 'script', label: '轻改稿' }, { id: 'production', label: '华生制作' }, { id: 'output', label: '成片与封面' }, { id: 'logs', label: '运行记录' }]
const activeView = ref('workbench'), detailTab = ref('source'), mobileDetail = ref(false)
const stories = ref<Story[]>([]), selected = ref<Story | null>(null), selectedId = ref<number | null>(null)
