const search = ref(''), categoryFilter = ref(''), statusFilter = ref('')
const channels = ref<Channel[]>([]), collections = ref<Collection[]>([])
const accounts = reactive<{ huasheng: Accounts; baijiahao: Accounts }>({ huasheng: { accounts: [] }, baijiahao: { accounts: [] } })
const accountDialog = ref(''), loading = ref(false), detailLoading = ref(false), busy = ref('')
const pageError = ref(''), detailError = ref(''), actionError = ref(''), dialogError = ref(''), notice = ref('')
const runTarget = ref<Target>('video'), huashengAccountName = ref(''), editionId = ref('')
