const progressSteps = computed(() => [
  { id: 'source', label: '来源', stages: ['download'], done: () => !!selected.value?.sourceVideoUrl },
  { id: 'transcript', label: '口播', stages: ['transcribe'], done: () => !!selected.value?.transcript },
  { id: 'analysis', label: '理解', stages: ['analyze'], done: () => !!selected.value?.analysis },
  { id: 'edit', label: '轻改对照', stages: ['edit', 'review'], done: () => !!selected.value?.revisions.find(item => item.id === selected.value?.currentRevisionId)?.review?.passed },
  { id: 'production', label: '制作', stages: ['produce', 'export'], done: () => !!selected.value?.editions.some(item => item.revisionId === selected.value?.currentRevisionId && item.videoUrl) },
  { id: 'output', label: '成片', stages: ['covers', 'publish'], done: () => !!selected.value?.editions.some(item => item.revisionId === selected.value?.currentRevisionId && item.status === 'package_ready') },
