let disposed = false, timer: ReturnType<typeof setInterval> | undefined, filterTimer: ReturnType<typeof setTimeout> | undefined, detailSequence = 0, listSequence = 0
const requestIds = new Map<string, string>()
function requestId(key: string) { if (!requestIds.has(key)) requestIds.set(key, crypto.randomUUID()); return requestIds.get(key)! }
