  if (disposed) return
  results.forEach((result, index) => { if (result.status === 'rejected') { pageError.value = errorMessage(result.reason); return }; if (index === 0) channels.value = result.value as Channel[]; else if (index === 1) collections.value = result.value as Collection[]; else updateAccounts(index === 2 ? 'huasheng' : 'baijiahao', result.value as Accounts) })
}
async function refresh() { if (loading.value) return; await Promise.allSettled([loadStories(), loadDetail(selectedId.value, true), loadSupporting()]) }
