async function selectStory(id: number) { selectedId.value = id; selected.value = null; sourceExcerpt.value = ''; actionError.value = ''; mobileDetail.value = true; await loadDetail(id) }
function changeView(value: string) { activeView.value = value; if (value === 'outputs') detailTab.value = 'output'; if (value !== 'channels') void loadStories(); else void loadSupporting() }
function filterChanged() { page.value = 1; void loadStories() }
