async function perform(key: string, action: () => Promise<void>, dialog = false) { if (busy.value) return; busy.value = key; actionError.value = ''; dialogError.value = ''; notice.value = ''; try { await action() } catch (error) { if (dialog) dialogError.value = errorMessage(error); else actionError.value = errorMessage(error) } finally { busy.value = '' } }
async function saveMetadata() {
  const story = selected.value, draft = editor.value; if (!story || !draft) return
  await perform('save', async () => {
    const ids = draft.relatedIds.split(/[,，\s]+/).filter(Boolean).map(Number)
    if (ids.some(id => !Number.isInteger(id) || id < 1)) throw new Error('关联故事编号需为正整数，使用逗号分隔。')
