    if (draft.title !== story.title) patch.title = draft.title
    if (draft.correctedTranscript !== (story.correctedTranscript || story.transcript)) patch.correctedTranscript = draft.correctedTranscript
    if (draft.narrator !== story.narrator) patch.narrator = draft.narrator
    if (draft.notes !== story.notes) patch.notes = draft.notes
    if (JSON.stringify(ids) !== JSON.stringify(story.relatedStoryIds)) patch.relatedStoryIds = ids
