}
async function saveRevision() {
  const story = selected.value, draft = editor.value; if (!story || !draft) return
  await perform('revision', async () => { const data = await api.post<Story>(`${base}/stories/${story.id}/revisions`, { expectedRevision: draft.baseRevisionId, patches: draft.patches }); draft.patchesDirty = false; draft.selection = blankSelection(); acceptStory(data); notice.value = '已另存文稿版本，正在检查句义、完整性、连贯性与原作体验。' })
